import com.sun.source.tree.*;import com.sun.source.util.*;import javax.tools.*;import java.nio.file.*;import java.util.*;
public final class ExtractDocxUi {
 public static void main(String[] args)throws Exception {
  String source=Files.readString(Path.of(args[0]));Set<String> names=new LinkedHashSet<>(List.of("REQUEST_DOCX_COPY","DocxPhase","DocxUi","docxUi","docxInterruptedCopy","startDocxExport","currentDocxUris","docxCurrent","presentDocxDialog","offerDocx","launchDocxPicker","handleDocxResult","finishDocx","cancelDocxExport","pauseDocxExport","showDocxNotice","docxFailureMessage","docxWarnings","onPause","onDestroy","onResume","styleDialog","historyDialogBuilder","workspaceDialogShown"));
  JavaCompiler c=ToolProvider.getSystemJavaCompiler();JavacTask task=(JavacTask)c.getTask(null,null,null,List.of("-proc:none"),null,c.getStandardFileManager(null,null,null).getJavaFileObjects(args[0]));CompilationUnitTree unit=task.parse().iterator().next();SourcePositions p=Trees.instance(task).getSourcePositions();Map<String,String> found=new LinkedHashMap<>();String resultRoute=null;String menuRoute=null;String paletteRoute=null;String workspaceRoute=null;
  for(Tree t:unit.getTypeDecls())if(t instanceof ClassTree)for(Tree m:((ClassTree)t).getMembers()){if(m instanceof MethodTree){MethodTree method=(MethodTree)m;if(method.getName().contentEquals("showWorkspace"))for(StatementTree statement:method.getBody().getStatements())if(statement.toString().contains("Export this document as DOCX"))workspaceRoute=source.substring((int)p.getStartPosition(unit,statement),(int)p.getEndPosition(unit,statement));if(method.getName().contentEquals("onActivityResult"))for(StatementTree statement:method.getBody().getStatements())if(statement instanceof IfTree&&((IfTree)statement).getCondition().toString().contains("REQUEST_DOCX_COPY"))resultRoute=source.substring((int)p.getStartPosition(unit,statement),(int)p.getEndPosition(unit,statement));if(method.getName().contentEquals("runMenuAction")||method.getName().contentEquals("lambda$showCommandPalette$59"))for(StatementTree statement:method.getBody().getStatements())if(statement instanceof SwitchTree)for(CaseTree branch:((SwitchTree)statement).getCases()){String label=branch.getExpression()==null?"":branch.getExpression().toString();if(method.getName().contentEquals("runMenuAction")&&label.equals("17"))menuRoute=source.substring((int)p.getStartPosition(unit,branch),(int)p.getEndPosition(unit,branch));if(method.getName().contentEquals("lambda$showCommandPalette$59")&&label.equals("16"))paletteRoute=source.substring((int)p.getStartPosition(unit,branch),(int)p.getEndPosition(unit,branch));}}String n=m instanceof MethodTree?((MethodTree)m).getName().toString():m instanceof ClassTree?((ClassTree)m).getSimpleName().toString():m instanceof VariableTree?((VariableTree)m).getName().toString():"";if(names.contains(n))found.put(n,source.substring((int)p.getStartPosition(unit,m),(int)p.getEndPosition(unit,m)));}
  if(!found.keySet().equals(names)){names.removeAll(found.keySet());throw new AssertionError("Missing actual workspace members: "+names);}
  if(resultRoute==null||menuRoute==null||paletteRoute==null||workspaceRoute==null)throw new AssertionError("Missing actual DOCX result/menu/palette routes");
  String helper=Files.readString(Path.of(args[3]));JavacTask helperTask=(JavacTask)c.getTask(null,null,null,List.of("-proc:none"),null,c.getStandardFileManager(null,null,null).getJavaFileObjects(args[3]));CompilationUnitTree hu=helperTask.parse().iterator().next();SourcePositions hp=Trees.instance(helperTask).getSourcePositions();List<String> capture=new ArrayList<>();for(Tree type:hu.getTypeDecls())if(type instanceof ClassTree)for(Tree member:((ClassTree)type).getMembers()){String n=member instanceof ClassTree?((ClassTree)member).getSimpleName().toString():member instanceof MethodTree?((MethodTree)member).getName().toString():"";if(List.of("Capture","uri","uris").contains(n))capture.add(helper.substring((int)hp.getStartPosition(hu,member),(int)hp.getEndPosition(hu,member)));}if(capture.size()!=3)throw new AssertionError("Missing real capture validation");
  Files.writeString(Path.of(args[2]),Files.readString(Path.of(args[1])).replace("/* MEMBERS */",String.join("\n",found.values())).replace("MainActivity.this","DocxHarness.this").replace("/* RESULT_ROUTE */",resultRoute).replace("/* MENU_ROUTE */",menuRoute).replace("/* PALETTE_ROUTE */",paletteRoute).replace("/* CAPTURE */",String.join("\n",capture)).replace("/* WORKSPACE_ROUTE */",workspaceRoute));
 }
}
